function Team({ team }) {
	const {
		teamName,
		clubLogo,
		points,
		wins,
		draws,
		losses,
		goalsFor,
		goalsAgainst,
		goalDifference,
	} = team;

	console.log(`team logo: ${clubLogo}`);
	return (
		<tr>
			<td className="team-name">
				<img src={clubLogo} alt="" /> {teamName}
			</td>
			<td>{points}</td>
			<td>{wins}</td>
			<td>{draws}</td>
			<td>{losses}</td>
			<td>{goalsFor}</td>
			<td>{goalsAgainst}</td>
			<td>{goalDifference}</td>
		</tr>
	);
}

export default Team;
